sed -i 's/\r$//' konf/compose.yaml 2>/dev/null; python3 - <<'PYEOF'
import yaml, re, sys
d = yaml.safe_load(open("konf/compose.yaml", encoding="utf-8")) or {}
sv = d.get("services") or {}
imgs = {n: str(s.get("image", "")) for n, s in sv.items()}
def find(pat): return [n for n, i in imgs.items() if re.search(pat, i)]
if not find(r"^postgres:"): sys.exit("postgres teenus puudub (A1)")
for kind in ("server-pgsql", "web-nginx-pgsql"):
    f = find(r"zabbix/zabbix-" + kind + ":")
    if not f: sys.exit(f"zabbix-{kind} image puudub (A1)")
    if not re.search(r":(alpine|ubuntu|ol)-7\.0\.\d+$", imgs[f[0]]): sys.exit(f"{imgs[f[0]]}: kasuta kindlat 7.0 versiooni, nt alpine-7.0.32 (mitte latest)")
txt = open("konf/compose.yaml", encoding="utf-8").read()
for m in re.finditer(r"POSTGRES_PASSWORD\s*[:=]\s*(\S+)", txt):
    if "${" not in m.group(1): sys.exit("parool on compose.yaml-is tavatekstina - pane see .env faili ja kasuta ${MUUTUJA}")
if "8080" not in txt: sys.exit("veebiliides peab olema pordil 8080")
print("compose.yaml OK:", ", ".join(f"{n}={i}" for n, i in imgs.items()))
PYEOF
